CREATE TABLE IF NOT EXISTS marketing_campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,objective VARCHAR(255) NULL,channel ENUM('email','social','search','content','mixed') NOT NULL DEFAULT 'email',status ENUM('draft','scheduled','active','paused','completed') NOT NULL DEFAULT 'draft',budget DECIMAL(15,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'USD',start_date DATE NULL,end_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_campaign_status(status));
CREATE TABLE IF NOT EXISTS marketing_segments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,description TEXT NULL,criteria_json JSON NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketing_campaign_segments (campaign_id BIGINT UNSIGNED NOT NULL,segment_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(campaign_id,segment_id),FOREIGN KEY(campaign_id) REFERENCES marketing_campaigns(id) ON DELETE CASCADE,FOREIGN KEY(segment_id) REFERENCES marketing_segments(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS marketing_drip_sequences (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,status ENUM('draft','active','paused') NOT NULL DEFAULT 'draft',trigger_type VARCHAR(80) NOT NULL DEFAULT 'lead_created',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketing_drip_steps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sequence_id BIGINT UNSIGNED NOT NULL,step_order INT NOT NULL,delay_minutes INT UNSIGNED NOT NULL DEFAULT 0,subject VARCHAR(255) NULL,body_html LONGTEXT NULL,template_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sequence_id) REFERENCES marketing_drip_sequences(id) ON DELETE CASCADE,INDEX idx_drip_step(sequence_id,step_order));
CREATE TABLE IF NOT EXISTS lead_marketing_scores (lead_id BIGINT UNSIGNED PRIMARY KEY,score INT NOT NULL DEFAULT 0,grade ENUM('cold','warm','hot','qualified') NOT NULL DEFAULT 'cold',last_calculated_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketing_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NULL,campaign_id BIGINT UNSIGNED NULL,event_type VARCHAR(80) NOT NULL,event_value DECIMAL(15,2) NULL,page_url VARCHAR(500) NULL,referrer VARCHAR(500) NULL,utm_source VARCHAR(120) NULL,utm_medium VARCHAR(120) NULL,utm_campaign VARCHAR(180) NULL,metadata_json JSON NULL,occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_event_lead(lead_id),INDEX idx_event_campaign(campaign_id),INDEX idx_event_type(event_type),INDEX idx_event_occurred(occurred_at),FOREIGN KEY(campaign_id) REFERENCES marketing_campaigns(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS marketing_attribution (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NOT NULL,campaign_id BIGINT UNSIGNED NULL,source VARCHAR(120) NULL,medium VARCHAR(120) NULL,first_touch_at DATETIME NULL,last_touch_at DATETIME NULL,conversion_value DECIMAL(15,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_attr_lead(lead_id),FOREIGN KEY(campaign_id) REFERENCES marketing_campaigns(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS marketing_content (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,content_type ENUM('blog','landing_page','case_study','service_page') NOT NULL DEFAULT 'blog',meta_title VARCHAR(255) NULL,meta_description VARCHAR(500) NULL,keywords VARCHAR(500) NULL,status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketing_conversions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NULL,campaign_id BIGINT UNSIGNED NULL,event_id BIGINT UNSIGNED NULL,conversion_type VARCHAR(100) NOT NULL,value DECIMAL(15,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'USD',converted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_conversion_campaign(campaign_id),INDEX idx_conversion_date(converted_at),FOREIGN KEY(campaign_id) REFERENCES marketing_campaigns(id) ON DELETE SET NULL,FOREIGN KEY(event_id) REFERENCES marketing_events(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS marketing_automation_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_name VARCHAR(120) NOT NULL,run_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,status ENUM('success','failed') NOT NULL,result_message VARCHAR(500) NULL,INDEX idx_automation_job(job_name,run_at));